# R golden fixtures for gaply_core's correlations as an analysis
# (Research OS, Phase 8H, decisions 338 to 341, capability
# stats.analyze.correlations).
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_corr_fixtures.R
#
# R is the reference, run outside Gaply (ADR-008): nothing of R is copied
# into Gaply. Base R only.
#
# Writes, next to this script:
#   * data_*.csv: one synthetic dataset per file (a two-line '#' header, then
#     `id,<variables>`, an empty cell for a missing value), each READ BACK
#     with read.csv(na.strings = "") and everything computed on what was read;
#   * cases.tsv: each case's file, its variables (headers, in the file's
#     column order), its coefficients, its missing handling and its missing
#     codes;
#   * expected.tsv: R's answer for every case, one statistic per row
#     (case, key, value), each value as %.17g ("Inf" and "-Inf" for an
#     infinite t), "NC:<code>" where Gaply must say "not computable" with
#     that code (decision 338's list, decided here from the values, as Gaply
#     decides it), and "refused" with its code for a case Gaply refuses;
#   * normal_tail.tsv: 2 * pnorm(-abs(z)) over a grid of z, for
#     stats_dist::normal_two_tailed, down to p 1e-300 and below (decision 341);
#   * measurements.txt: what this script measured about R (the clamp of cor,
#     the tie correction of Kendall's variance, the time of the big pair).
#
# The rows are chosen HERE, before any call, so that R's use= rules never
# decide them (decision 340): listwise, the rows in which every variable of
# the case has a value; pairwise, for each pair the rows in which both have
# one. A missing code ticked for the case is a missing value in every one of
# its variables. Descriptives: listwise over the complete rows; pairwise over
# the variable's own values in the rows with values in two variables or more.
#
# Where each number comes from:
#   * Pearson: cor.test(x, y, method = "pearson"): r, t, df, p and, from four
#     rows, its Fisher interval (R. A. Fisher, 1921), whose SE is
#     1 / sqrt(n - 3);
#   * Spearman: rho is cor.test(method = "spearman", exact = FALSE)'s
#     estimate. cor.test's statistic for Spearman is S = (n^3 - n)(1 - rho)/6,
#     not t: t = rho sqrt((n - 2) / (1 - rho^2)) and its p, 2 pt(-|t|, n - 2),
#     are computed HERE. THE SAME FORMULA IS WRITTEN TWICE, here and in
#     gaply_core (decision 339), so this checks the arithmetic, not the method.
#     A rho of +-1 has an infinite t and a p of 0;
#   * Kendall: cor.test(method = "kendall", exact = FALSE, continuity =
#     FALSE): tau-b (?cor: "When there are ties, Kendall's tau_b is
#     computed"), z and p;
#   * the Spearman and Kendall intervals have no base R function. They are
#     computed HERE by decision 339's formulas, Fisher's z with Bonett and
#     Wright's SE sqrt((1 + rho^2/2) / (n - 3)) and Fieller, Hartley and
#     Pearson's sqrt(0.437 / (n - 4)): THE SAME FORMULA WRITTEN TWICE. A
#     coefficient of +-1 has the interval [+-1, +-1], tanh's limit, as R's
#     cor.test gives it for Pearson;
#   * the descriptives: mean() and sd() over the rows above.
#
# Not computable, decided here from the values as Gaply decides them: a pair
# of fewer than 3 rows (pair_too_few_rows); a variable constant over the
# pair's rows (variable_constant); the interval of n <= 3 (Pearson,
# Spearman) or n <= 4 (Kendall) (interval_too_few_rows); a mean of no values
# (no_values), an SD of fewer than two (too_few_values).
#
# The 100,000-row pair `big` has no CSV: row i (0-based) is
# x = ((i * 7919) mod 10007) / 100 and y = x * 0.3 + ((i * 104729) mod 1009)
# / 50, the same IEEE operations on both sides, so the doubles are equal;
# gaply_core's golden builds it from this formula too.

HEADER <- c(
  "# Synthetic data for gaply_core's correlations R golden fixtures (Research OS, Phase 8H).",
  "# Generated by /usr/local/bin/Rscript make_corr_fixtures.R (do not edit by hand)."
)
OUT <- "# written by: /usr/local/bin/Rscript make_corr_fixtures.R"

args <- commandArgs(trailingOnly = FALSE)
here <- dirname(normalizePath(sub("^--file=", "", args[grep("^--file=", args)])))
setwd(here)

fmt <- function(x) {
  if (is.character(x)) return(x)
  if (is.na(x)) return("NA")
  if (is.infinite(x)) return(if (x > 0) "Inf" else "-Inf")
  sprintf("%.17g", x)
}

# A data file: id, then the named columns; NA written as an empty cell.
# Returns the file READ BACK.
write_data <- function(file, cols) {
  n <- length(cols[[1]])
  cell <- function(v) ifelse(is.na(v), "", as.character(v))
  body <- do.call(paste, c(list(seq_len(n)), lapply(cols, cell), sep = ","))
  writeLines(c(HEADER, paste(c("id", names(cols)), collapse = ","), body), file)
  read.csv(file, comment.char = "#", na.strings = "", check.names = FALSE)
}

measure <- character()
note <- function(...) measure <<- c(measure, paste0(...))

set.seed(8008)
r4 <- function(v) round(v, 4)

# ---- the data ---------------------------------------------------------------

files <- list()

# Ten variables, 30 rows: mixed signs, strong, weak and near zero.
z <- matrix(rnorm(30 * 10), 30, 10)
mix <- diag(10)
mix[1, 2] <- 0.9; mix[1, 3] <- -0.7; mix[2, 4] <- 0.4; mix[3, 5] <- 0.2
mix[4, 6] <- -0.95; mix[5, 7] <- 0.6; mix[6, 8] <- 0.3; mix[9, 10] <- -0.5
basic <- z %*% mix
cols <- setNames(lapply(1:10, function(j) r4(basic[, j] * 10 + 50)), sprintf("v%02d", 1:10))
files$basic <- write_data("data_basic.csv", cols)

# 10 rows, five variables.
z <- matrix(rnorm(10 * 5), 10, 5)
files$n10 <- write_data("data_n10.csv", setNames(lapply(1:5, function(j)
  r4(z[, j] + 0.6 * z[, 1] * (j > 1))), c("a", "b", "c", "d", "e")))

