files$n4 <- write_data("data_n4.csv", list(x = c(1, 2, 3.5, 4), y = c(9.5, 7, 7.25, 1), w = c(3, 1, 4, 1.5)))
files$n5 <- write_data("data_n5.csv", list(x = c(2.1, 3.4, 1.9, 5.5, 4.2), y = c(10, 12.5, 9, 13, 14.75), w = c(0.5, -1, 2, 0.25, 1)))

# Perfect coefficients: a line up and down (all three +-1), a monotone curve
# (Spearman and Kendall 1, Pearson below 1).
x <- 1:8
files$perfect <- write_data("data_perfect.csv", list(x = x, up = 2 * x + 3, down = 20 - x, cube = x^3))
# Perfect with ties: the same order and the same ties, or exactly reversed.
files$perfect_ties <- write_data("data_perfect_ties.csv", list(
  a = c(1, 1, 2, 3, 3, 4), b = c(10, 10, 20, 30, 30, 45), c = c(9, 9, 7, 5, 5, 1)))

# Collinear data for which stats_verify's pearson_r gives 1 + 1 ulp (found by
# emulating its arithmetic, 1 Nov 2026), and four monotone rows for which
# stats_verify::spearman gives 1 - 2 ulp (Level 1's finding, stats_l1/compute.rs).
files$ulp <- write_data("data_ulp.csv", list(
  x = c(0.3, 0.6, 0.9, 1.2, 1.5), y = c(-0.31, -0.22, -0.13, -0.04, 0.05)))
files$spearman_ulp <- write_data("data_spearman_ulp.csv", list(x = c(1, 2, 3, 4), y = c(2, 5, 10, 17)))

# |r| near 1: 0.999999.
x <- seq(1, 30)
e <- rnorm(30)
e <- e - mean(e)
files$near_one <- write_data("data_near_one.csv", list(x = x, y = r4(x + e * 0.0124), z = r4(-x + e * 0.0124)))

# Ties in both variables.
files$ties <- write_data("data_ties.csv", list(
  x = c(1, 2, 2, 3, 3, 3, 4, 5, 5, 6, 7, 7, 8, 8, 8, 9, 10, 10, 11, 12),
  y = c(3, 1, 3, 2, 4, 4, 4, 5, 3, 6, 6, 8, 7, 7, 9, 8, 9, 9, 12, 10)))

# Five-point Likert items, 40 rows, heavy ties.
lat <- rnorm(40)
lik <- function(w) pmin(5, pmax(1, round(3 + w * lat + rnorm(40, 0, 0.9))))
files$likert <- write_data("data_likert.csv", list(q1 = lik(1), q2 = lik(0.8), q3 = lik(-0.6), q4 = lik(0.2), q5 = lik(1.1)))

# A 1e9 offset.
u <- round(rnorm(15) * 3, 2)
files$offset <- write_data("data_offset.csv", list(
  a = 1e9 + u, b = 1e9 + round(0.8 * u + rnorm(15), 2), c = round(-0.5 * u + rnorm(15), 2)))

# Missing cells in different rows, and a code (-99) in some cells.
z <- matrix(rnorm(25 * 4), 25, 4)
m <- lapply(1:4, function(j) r4(z[, j] + 0.7 * z[, 1] * (j > 1)))
m[[1]][c(2, 9)] <- NA; m[[2]][c(4, 9, 17)] <- NA; m[[3]][c(6, 21)] <- NA; m[[4]][c(11, 12)] <- NA
m[[1]][14] <- -99; m[[3]][c(3, 19)] <- -99; m[[4]][23] <- -99
files$missing <- write_data("data_missing.csv", setNames(m, c("p", "q", "r", "s")))

# A constant variable.
files$constant <- write_data("data_constant.csv", list(
  x = c(1, 3, 2, 5, 4, 6, 8, 7, 9, 10), k = rep(4.5, 10), y = c(2, 1, 4, 3, 6, 5, 8, 9, 7, 10)))

# A pair with 2 rows under pairwise; under listwise, 1 complete row.
files$pair_few <- write_data("data_pair_few.csv", list(
  x = c(1, 2, 3, 4, 5, NA, NA, NA), y = c(2, 1, 4, 3, 6, 5, 7, 8), z = c(NA, NA, NA, 9, 7, NA, 3, 1)))

# p below 1e-100, and p of 0: 1000 rows.
a <- rnorm(1000)
files$small_p <- write_data("data_small_p.csv", list(
  a = r4(a), b = r4(0.7 * a + sqrt(1 - 0.49) * rnorm(1000)), c = r4(a + 0.1 * rnorm(1000))))

# ---- the cases --------------------------------------------------------------

ALL <- c("pearson", "spearman", "kendall")
cases <- list(
  list(name = "k2_n30", file = "basic", vars = c("v01", "v02"), coef = ALL, missing = "pairwise", codes = numeric()),
  list(name = "k10_n30", file = "basic", vars = sprintf("v%02d", 1:10), coef = ALL, missing = "listwise", codes = numeric()),
  list(name = "k5_n30_pk", file = "basic", vars = sprintf("v%02d", c(2, 4, 6, 8, 10)), coef = c("pearson", "kendall"), missing = "pairwise", codes = numeric()),
  list(name = "k5_n10", file = "n10", vars = c("a", "b", "c", "d", "e"), coef = ALL, missing = "listwise", codes = numeric()),
  list(name = "n3", file = "n3", vars = c("x", "y"), coef = ALL, missing = "pairwise", codes = numeric()),
  list(name = "n4", file = "n4", vars = c("x", "y", "w"), coef = ALL, missing = "listwise", codes = numeric()),
  list(name = "n5", file = "n5", vars = c("x", "y", "w"), coef = ALL, missing = "pairwise", codes = numeric()),
  list(name = "perfect", file = "perfect", vars = c("x", "up", "down", "cube"), coef = ALL, missing = "listwise", codes = numeric()),
  list(name = "perfect_ties", file = "perfect_ties", vars = c("a", "b", "c"), coef = ALL, missing = "pairwise", codes = numeric()),
  list(name = "pearson_ulp", file = "ulp", vars = c("x", "y"), coef = ALL, missing = "pairwise", codes = numeric()),
  list(name = "spearman_ulp", file = "spearman_ulp", vars = c("x", "y"), coef = ALL, missing = "pairwise", codes = numeric()),
  list(name = "near_one", file = "near_one", vars = c("x", "y", "z"), coef = ALL, missing = "listwise", codes = numeric()),
  list(name = "ties", file = "ties", vars = c("x", "y"), coef = ALL, missing = "pairwise", codes = numeric()),
  list(name = "likert", file = "likert", vars = c("q1", "q2", "q3", "q4", "q5"), coef = ALL, missing = "listwise", codes = numeric()),
  list(name = "offset", file = "offset", vars = c("a", "b", "c"), coef = ALL, missing = "pairwise", codes = numeric()),
  list(name = "missing_pairwise", file = "missing", vars = c("p", "q", "r", "s"), coef = ALL, missing = "pairwise", codes = -99),
  list(name = "missing_listwise", file = "missing", vars = c("p", "q", "r", "s"), coef = ALL, missing = "listwise", codes = -99),
  list(name = "missing_uncoded", file = "missing", vars = c("p", "q", "s"), coef = c("spearman"), missing = "pairwise", codes = numeric()),
  list(name = "constant", file = "constant", vars = c("x", "k", "y"), coef = ALL, missing = "pairwise", codes = numeric()),
  list(name = "pair_few", file = "pair_few", vars = c("x", "y", "z"), coef = ALL, missing = "pairwise", codes = numeric()),
  list(name = "listwise_refused", file = "pair_few", vars = c("x", "y", "z"), coef = ALL, missing = "listwise", codes = numeric()),
  list(name = "small_p", file = "small_p", vars = c("a", "b", "c"), coef = ALL, missing = "listwise", codes = numeric()),
  list(name = "big", file = "-", vars = c("x", "y"), coef = ALL, missing = "listwise", codes = numeric())
)

# ---- the computation --------------------------------------------------------

expected <- character()
put <- function(case, key, value) expected <<- c(expected, paste(case, key, fmt(value), sep = "\t"))

z975 <- qnorm(0.975)
fisher <- function(est, se) {
  if (abs(est) == 1) return(c(est, est))
  tanh(atanh(est) + c(-1, 1) * z975 * se)
}

# Decision 339's variance of S, for the tie correction's check against cor.test.
kendall_z <- function(x, y) {
  n <- length(x)
  s <- 0
  # S exactly: a sum of +-1 and 0 terms, an integer far below 2^53.
  for (i in 1:(n - 1)) s <- s + sum(sign(x[i] - x[(i + 1):n]) * sign(y[i] - y[(i + 1):n]))
  tx <- table(x); ty <- table(y)
  v0 <- n * (n - 1) * (2 * n + 5)
  vt <- sum(tx * (tx - 1) * (2 * tx + 5)); vu <- sum(ty * (ty - 1) * (2 * ty + 5))
  v1 <- sum(tx * (tx - 1)) * sum(ty * (ty - 1))
  v2 <- sum(tx * (tx - 1) * (tx - 2)) * sum(ty * (ty - 1) * (ty - 2))
  v <- (v0 - vt - vu) / 18 + v1 / (2 * n * (n - 1)) + v2 / (9 * n * (n - 1) * (n - 2))
  s / sqrt(v)
}

constant <- function(v) all(v == v[1])

# Rank correlation's own definition of +-1: the two variables rank the rows
# identically (the same order and the same ties), or exactly in reverse.
# Then rho and tau-b are +-1 exactly. R's arithmetic can miss that by two
# units in the last place (measured: data_ulp.csv, n = 5, where cor.test
# gives 0.99999999999999978 for both, and so a finite t and a p of 4e-24);
# where it does, the exact value is written and R's is recorded in
# measurements.txt (decision 341's "near +-1", stated in the report).
rank_sign <- function(x, y) {
  if (identical(rank(x), rank(y))) return(1)
  if (identical(rank(x), length(x) + 1 - rank(y))) return(-1)
  0
}

pair <- function(case, coef, i, j, x, y) {
  key <- sprintf("%s.%d-%d", coef, i - 1, j - 1)
  n <- length(x)
  put(case, paste0(key, ".n"), n)
  if (n < 3) return(put(case, paste0(key, ".nc"), "NC:pair_too_few_rows"))
  if (constant(x) || constant(y)) return(put(case, paste0(key, ".nc"), "NC:variable_constant"))
  if (coef == "pearson") {
    ct <- cor.test(x, y, method = "pearson")
    est <- unname(ct$estimate); t <- unname(ct$statistic)
    put(case, paste0(key, ".estimate"), est)
    put(case, paste0(key, ".statistic"), t)
    put(case, paste0(key, ".df"), unname(ct$parameter))
    put(case, paste0(key, ".p"), ct$p.value)
    ci <- if (n <= 3) NULL else fisher(est, 1 / sqrt(n - 3))
    if (!is.null(ci) && n >= 4 && abs(est) < 1) {
      stopifnot(max(abs(ci - ct$conf.int)) <= 4 * .Machine$double.eps)
    }
  } else if (coef == "spearman") {
    est <- unname(cor.test(x, y, method = "spearman", exact = FALSE)$estimate)
    perfect <- rank_sign(x, y)
    if (perfect != 0 && est != perfect) {
      note(sprintf("exact +-1 written for %s %s: R's rho %.17g, ranks %s", case, key, est,
                   if (perfect > 0) "identical" else "exactly reversed"))
      est <- perfect
    }
    t <- if (abs(est) == 1) Inf * sign(est) else est * sqrt((n - 2) / (1 - est^2))
    p <- if (is.infinite(t)) 0 else 2 * pt(-abs(t), n - 2)
    put(case, paste0(key, ".estimate"), est)
    put(case, paste0(key, ".statistic"), t)
    put(case, paste0(key, ".df"), n - 2)
    put(case, paste0(key, ".p"), p)
    ci <- if (n <= 3) NULL else fisher(est, sqrt((1 + est^2 / 2) / (n - 3)))
  } else {
    ct <- cor.test(x, y, method = "kendall", exact = FALSE, continuity = FALSE)
    est <- unname(ct$estimate)
    perfect <- rank_sign(x, y)
    if (perfect != 0 && est != perfect) {
      note(sprintf("exact +-1 written for %s %s: R's tau-b %.17g, ranks %s (z and p are cor.test's)", case, key, est,
                   if (perfect > 0) "identical" else "exactly reversed"))
      est <- perfect
    }
    put(case, paste0(key, ".estimate"), est)
    zz <- kendall_z(x, y)
    # At 100,000 rows cor.test's z is off by about 2e-7 relative (measured
    # against this script's exact S and decision 339's variance, and an
    # exact-fraction evaluation outside R, 1 Nov 2026): there the formula's z
    # is written, and cor.test's recorded.
    if (n > 2000) {
      note(sprintf("kendall z at n = %d, %s %s: cor.test's %.17g, decision 339's with exact S %.17g, relative difference %.3g; the latter written",
                   n, case, key, ct$statistic, zz, abs(zz - ct$statistic) / abs(zz)))
      put(case, paste0(key, ".statistic"), zz)
    } else {
      put(case, paste0(key, ".statistic"), unname(ct$statistic))
    }
    put(case, paste0(key, ".p"), ct$p.value)
    ci <- if (n <= 4) NULL else fisher(est, sqrt(0.437 / (n - 4)))
    if (n <= 2000) {
      rel <- if (ct$statistic == 0) abs(zz) else abs(zz - ct$statistic) / abs(ct$statistic)
      if (case == "likert" || case == "ties") {
        note(sprintf("kendall tie correction, %s %s: decision 339's z %.17g, cor.test's z %.17g, relative difference %.3g",
                     case, key, zz, ct$statistic, rel))
      }
      if (!(rel < 1e-12)) stop(sprintf("kendall z check: %s %s n=%d decision 339's z %.17g, cor.test's %.17g", case, key, n, zz, ct$statistic))
    }
  }
  if (is.null(ci)) {
    put(case, paste0(key, ".ci"), "NC:interval_too_few_rows")
  } else {
    put(case, paste0(key, ".ci_lower"), ci[1])
    put(case, paste0(key, ".ci_upper"), ci[2])
  }
}

case_rows <- character()
for (cs in cases) {
  if (cs$file == "-") {
    i <- 0:99999
    xb <- ((i * 7919) %% 10007) / 100
    yb <- xb * 0.3 + ((i * 104729) %% 1009) / 50
    d <- data.frame(x = xb, y = yb)
  } else {
    d <- files[[cs$file]]
  }
  v <- d[, cs$vars, drop = FALSE]
  coded <- as.data.frame(lapply(v, function(col) col %in% cs$codes & !is.na(col)))
  missing <- as.data.frame(lapply(v, is.na))
  for (k in seq_along(v)) v[[k]][coded[[k]]] <- NA
  has <- !is.na(as.matrix(v))
  case_rows <- c(case_rows, paste(cs$name, if (cs$file == "-") "-" else sprintf("data_%s.csv", cs$file),
                                  paste(cs$vars, collapse = " "), paste(cs$coef, collapse = " "), cs$missing,
                                  if (length(cs$codes)) paste(cs$codes, collapse = " ") else "-", sep = "\t"))
  if (cs$missing == "listwise") {
    used <- rowSums(has) == ncol(v)
    if (sum(used) < 3) { put(cs$name, "refused", "too_few_complete_rows"); next }
    # Each row left out once, under the first variable without a value.
    ex <- integer()
    for (r in which(!used)) {
      k <- which(!has[r, ])[1]
      code <- if (coded[[k]][r]) "missing_code" else "missing_value"
      key <- sprintf("excl.%s.%d", code, k - 1)
      ex[key] <- (if (is.na(ex[key])) 0L else ex[key]) + 1L
    }
    for (key in sort(names(ex))) put(cs$name, key, ex[[key]])
  } else {
    used <- rowSums(has) >= 2
    best <- 0
    for (i in 1:(ncol(v) - 1)) for (j in (i + 1):ncol(v)) best <- max(best, sum(has[, i] & has[, j]))
    if (best < 3) { put(cs$name, "refused", "no_pair_of_three"); next }
    if (sum(!used) > 0) put(cs$name, "excl.fewer_than_two_values", sum(!used))
  }
  put(cs$name, "rows_used", sum(used))
  for (k in seq_along(v)) {
    vals <- v[[k]][used & has[, k]]
    put(cs$name, sprintf("desc.%d.n", k - 1), length(vals))
    put(cs$name, sprintf("desc.%d.mean", k - 1), if (length(vals) == 0) "NC:no_values" else mean(vals))
    put(cs$name, sprintf("desc.%d.sd", k - 1), if (length(vals) < 2) "NC:too_few_values" else sd(vals))
  }
  t0 <- proc.time()[["elapsed"]]
  for (coef in cs$coef) {
    for (i in 1:(ncol(v) - 1)) for (j in (i + 1):ncol(v)) {
      rows <- if (cs$missing == "listwise") used else has[, i] & has[, j]
      pair(cs$name, coef, i, j, v[[i]][rows], v[[j]][rows])
    }
  }
  if (cs$name == "big") note(sprintf("big (100,000 rows, one pair, all three coefficients): R took %.1f s", proc.time()[["elapsed"]] - t0))
}

# ---- measurements ------------------------------------------------------------

u <- files$ulp
note(sprintf("cor clamps: cor(x, y) on data_ulp.csv (collinear) is %a (%s 1)", cor(u$x, u$y),
             if (cor(u$x, u$y) == 1) "==" else "!="))
s <- files$spearman_ulp
note(sprintf("cor of ranks on data_spearman_ulp.csv is %a", cor(rank(s$x), rank(s$y))))
p <- files$perfect
note(sprintf("cor(x, up) on data_perfect.csv is %a; cor(x, down) is %a", cor(p$x, p$up), cor(p$x, p$down)))

writeLines(c(OUT, paste0("# ", R.version.string), "case\tfile\tvariables\tcoefficients\tmissing\tmissing_codes", case_rows), "cases.tsv")
writeLines(c(OUT, paste0("# ", R.version.string), "case\tkey\tvalue", expected), "expected.tsv")

zs <- c(seq(0, 8, by = 0.125), seq(8.5, 37, by = 0.5), 37.25, 37.5, 37.75, 38, 38.5, 39, 40)
